function Navbar({ page, setPage }) {
  const [scrolled, setScrolled] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  useEffect(() => {
    const fn = () => setScrolled(window.scrollY > 30);
    window.addEventListener('scroll', fn);
    return () => window.removeEventListener('scroll', fn);
  }, []);
  const nav = (p) => { setPage(p); setMobileOpen(false); window.scrollTo({ top: 0, behavior: 'smooth' }); };
  return (
    <>
      <nav className={`navbar${scrolled ? ' scrolled' : ''}`}>
        <div className="nav-logo" onClick={() => nav('home')}>
          <img src={`data:image/jpeg;base64,${LOGO_B64}`} alt="SHIPX Global Logo" />
          <div className="nav-logo-text">
            <div className="brand">SHIPX GLOBAL</div>
            <div className="sub">PVT LTD</div>
          </div>
        </div>
        <ul className="nav-links">
          {[['home','Home'],['about','About Us'],['feedback','Feedback']].map(([p,l]) => (
            <li key={p}><a className={page===p?'active':''} onClick={() => nav(p)} style={{cursor:'pointer'}}>{l}</a></li>
          ))}
        </ul>
        <button className="nav-cta" onClick={() => nav('feedback')}>Get Quote</button>
        <button className="hamburger" onClick={() => setMobileOpen(!mobileOpen)} aria-label="menu">
          <span/><span/><span/>
        </button>
      </nav>
      {mobileOpen && (
        <div className="mobile-menu">
          {[['home','HOME'],['about','ABOUT US'],['feedback','FEEDBACK']].map(([p,l]) => (
            <a key={p} className={page===p?'active':''} onClick={() => nav(p)} style={{cursor:'pointer'}}>{l}</a>
          ))}
          <button className="btn-gold" style={{marginTop:8}} onClick={() => nav('feedback')}>Get a Quote</button>
        </div>
      )}
    </>
  );
}


